// Find the bug (Phase 5): a practice problem whose starter is the reference
// with one planted error (generated by `tutor site-data` from the unit, never
// typed). The learner runs the problem's convergence tests on their code
// through `tutor serve`: each test is Julia appended to the code that prints
// one line, read here with the test's regex (the same one `tutor course
// verify` reads with PCRE). Feedback fades: first the measured table and what
// each failing test measures, then the problem's hints one at a time. The
// planted line and its misconception are shown only once the code passes the
// grader and every test on the same code.
import type { BugTest, Problem, Unit } from "./course";

export interface BugReading {
  name: string;
  /** the measured number; null when no single line matched (an error, a crash) */
  value: number | null;
  passed: boolean;
}

export interface BugRecord {
  /** test runs made (each runs every test) */
  runs: number;
  /** hints shown */
  hints: number;
  /** passed the grader and every test on the same code; the record freezes then */
  fixed: boolean;
}

/** The code a test runs: the learner's code, then the test (as `Course.bug_test_code`). */
export const bugTestCode = (code: string, t: BugTest) => code.replace(/\s+$/, "") + "\n\n" + t.code;

/** Julia prints Inf and NaN, which Number() does not read. */
function readNumber(s: string): number | null {
  if (/^[-+]?Inf$/.test(s)) return s.startsWith("-") ? -Infinity : Infinity;
  if (s === "NaN") return NaN;
  const v = Number(s);
  return s.trim() === "" || Number.isNaN(v) ? null : v;
}

/** The test's measured value in a run's output: null unless exactly one line matches its row. */
export function readBugTest(t: BugTest, output: string): number | null {
  let re: RegExp;
  try { re = new RegExp(t.row); } catch { return null; }
  const hits = output.split("\n").map((l) => re.exec(l)).filter((x): x is RegExpExecArray => x !== null);
  if (hits.length !== 1 || !hits[0].groups) return null;
  return readNumber(hits[0].groups.m ?? "");
}

/** Passes when the reading lies in the test's inclusive range; no reading, or NaN, fails. */
export const bugTestPasses = (t: BugTest, v: number | null) =>
  v !== null && !Number.isNaN(v) && v >= t.expect[0] && v <= t.expect[1];

export const reading = (t: BugTest, output: string): BugReading => {
  const value = readBugTest(t, output);
  return { name: t.name, value, passed: bugTestPasses(t, value) };
};

/**
 * Hints may be opened once the tests have been run (their table is the first
 * feedback), or at once when they cannot be run here (no `tutor serve`).
 */
export const hintsOpen = (runs: number, canRun: boolean) => runs > 0 || !canRun;

/** The record after one more test run, hint or fix; a fixed record never changes again. */
export function bumpBug(r: BugRecord | undefined, what: "run" | "hint" | "fixed"): BugRecord {
  const b = r ?? { runs: 0, hints: 0, fixed: false };
  if (b.fixed) return b;
  if (what === "run") return { ...b, runs: b.runs + 1 };
  if (what === "hint") return { ...b, hints: b.hints + 1 };
  return { ...b, fixed: true };
}

export interface KcBugs {
  kc: string;
  fixed: number;
  /** hints used across the fixed ones */
  hints: number;
  total: number;
}

/** Fixed bugs per knowledge component over problems the learner has worked on (a record exists). */
export function bugRates(records: Record<string, BugRecord>, units: Unit[]): KcBugs[] {
  const by = new Map<string, KcBugs>();
  for (const u of units)
    for (const p of u.problems) {
      const r = records[p.id];
      if (!p.bug || !r) continue;
      const k = by.get(p.bug.kc) ?? { kc: p.bug.kc, fixed: 0, hints: 0, total: 0 };
      k.total += 1;
      if (r.fixed) { k.fixed += 1; k.hints += r.hints; }
      by.set(p.bug.kc, k);
    }
  return [...by.values()].sort((a, b) => a.kc.localeCompare(b.kc));
}

/** The find-the-bug problems of a unit. */
export const unitBugs = (u: Unit): Problem[] => u.problems.filter((p) => p.bug);
